#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Managed Linux scope rollout; exact legacy compatibility for old subjects."""

from integrity_client_memory.configuration import value as _integrity_value, require_config as _integrity_require_config
import base64
import hashlib
import json
import os
from pathlib import Path
import re
import sys
import types

LEGACY_RAW = ''
LEGACY_SHA = '94209cee0aceb0bbd61c270a8bf5a5baec70c236552acbbee161b8452d8f77db'
COMPLETE_RAW = ''
COMPLETE_SHA = 'ad97a2f75474e6e3283e9d4bd1b937381be2b509b68896ad7e942972aa187f3c'
VERIFIED_NATIVE_SUBJECTS = frozenset()  # No publisher-enrolled sessions.
RUNTIME_CANARY = False
NATIVE_PYTHON = _integrity_value('path_92fad53f3db0')
NATIVE_PREFIX = _integrity_value('path_8a9e4b9f5f66')
if __name__ == "__main__":
    _integrity_require_config()

if __name__ == '__main__' and sys.prefix != NATIVE_PREFIX:
    runtime = Path(NATIVE_PYTHON).resolve(strict=True)
    info = runtime.stat()
    if (runtime != Path(NATIVE_PYTHON) or info.st_uid != 0
            or info.st_mode & 0o022
            or hashlib.sha256(runtime.read_bytes()).hexdigest() != _integrity_value('pin_da5fa25612d5')):
        raise RuntimeError('scope_native_runtime_pin_invalid')
    # Native stdin and arguments pass through unchanged; no caller/env fabrication.
    os.execv(NATIVE_PYTHON, [NATIVE_PYTHON, '-B', __file__, *sys.argv[1:]])

def _module(name, encoded, expected):
    raw = base64.b64decode(encoded)
    if hashlib.sha256(raw).hexdigest() != expected:
        raise RuntimeError('scope_rollout_source_digest_mismatch')
    module = types.ModuleType(name)
    module.__file__ = __file__
    sys.modules[name] = module
    exec(compile(raw, __file__, 'exec'), module.__dict__)
    return module

_old = _module('_integrity_scope_exact_legacy', LEGACY_RAW, LEGACY_SHA)
_new = _module('_integrity_scope_complete_linux', COMPLETE_RAW, COMPLETE_SHA)
_old_handle = _old.handle
_old_record = _old.record_prompt
for _key, _value in vars(_old).items():
    if not _key.startswith('__'):
        globals().setdefault(_key, _value)

def _strict(state):
    return (state is None or not state.get('instructions')
            or state.get('session') in VERIFIED_NATIVE_SUBJECTS
            or state.get('scope_capture_protocol') == 'integrity/complete-scope/v1')

def explicit_replacement(prompt):
    if not isinstance(prompt, str):
        return False
    text = prompt.strip()
    return text.startswith('INTEGRITY_SCOPE_REPLACE\n') or text.casefold().startswith(('новая задача:', 'задача:'))

def _caller_fault(event, payload, subject):
    uuid = r'[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}'
    if not re.fullmatch(uuid, subject):
        return 'scope_native_caller_mismatch'
    native = os.environ.get('CODEX_THREAD_ID')
    if native is not None and native != subject:
        return 'scope_native_caller_mismatch'
    if event in {'PreToolUse', 'UserPromptSubmit'} and not re.fullmatch(uuid, str(payload.get('turn_id', ''))):
        return 'scope_native_turn_missing'
    return None

def _observe_rollout_route(event, payload, route):
    # Diagnostic observation is opt-in; disabled profiles read no diagnostic bindings.
    if not RUNTIME_CANARY:
        return
    # One real own callback receipt; no scope inputs, refs, env values or secrets.
    if event != 'PreToolUse' or _old.session_key(payload) != _integrity_value('binding_db8055e0e030'):
        return
    if Path(_integrity_value('path_ba69d17f10cf')).exists():
        return
    native = os.environ.get('CODEX_THREAD_ID')
    record = {'protocol': 'integrity/scope-rollout-callback/v1', 'event': event,
              'route': route, 'caller_validated': True,
              'native_env_present': native is not None,
              'native_env_matches': native == _old.session_key(payload),
              'dispatcher_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
              'complete_source_sha256': COMPLETE_SHA,
              'runtime_executable': sys.executable, 'runtime_prefix': sys.prefix}
    if RUNTIME_CANARY:
        import time
        import linux_runtime_factory as factory
        profile = json.loads(factory.protected_bytes(factory.CONFIG, private=True))
        sdk = factory.UnixOwnerSDK(_old.session_key(payload), time.monotonic() + 18, profile)
        sdk.turn_id = payload['turn_id']
        try:
            subject = _old.session_key(payload)
            meta = sdk.request('thread/read', {'threadId':subject,'includeTurns':False}, 6)
            page = sdk.request('thread/turns/list', {'threadId':subject,'limit':1,
                               'sortDirection':'desc','itemsView':'full'}, 8)
            record['native_callback_sdk_PASS'] = (meta.get('thread',{}).get('id') == subject
                and page.get('data',[{}])[0].get('id') == payload['turn_id'])
            record['native_rpc'] = 2
        except Exception as error:
            record['native_callback_sdk_PASS'] = False
            record['safe_failure'] = factory.safe_failure(error, 'scope-runtime-canary')['code']
        finally:
            sdk.close()
    try:
        fd = os.open(_integrity_value('path_ba69d17f10cf'),
                     os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        with os.fdopen(fd, 'w') as stream:
            json.dump(record, stream, sort_keys=True)
            stream.write('\n'); stream.flush(); os.fsync(stream.fileno())
    except OSError:
        pass

def record_prompt(state, prompt, turn, *, force_task=False):
    # Verified delegation starts a fresh complete task for its own subject.
    if force_task or _strict(state) or explicit_replacement(prompt):
        return _new.record_prompt(state, prompt, turn, force_task=force_task)
    return _old_record(state, prompt, turn, force_task=force_task)

def handle(event, payload, store):
    subject = _old.session_key(payload)
    fault = _caller_fault(event, payload, subject)
    if fault:
        text = 'INTEGRITY SCOPE SYNAPSE fault: ' + fault
        return _old.deny_output(text) if event == 'PreToolUse' else _old.context_output(event, text)
    with store.locked(subject):
        state = store.load(subject)
    text = payload.get('prompt') or payload.get('user_prompt')
    replacement = event == 'UserPromptSubmit' and explicit_replacement(text)
    if _strict(state) or replacement:
        _observe_rollout_route(event, payload, 'complete')
        return _new.handle(event, payload, store)
    # Existing unknown legacy anchors stay byte-for-byte under the previous
    # policy until a genuine replacement task is captured. No complete flag,
    # private source, admission or lease is fabricated by this compatibility path.
    _observe_rollout_route(event, payload, 'legacy')
    return _old_handle(event, payload, store)

_old.handle = handle
_old.record_prompt = record_prompt

if __name__ == "__main__":
    _integrity_require_config()

if __name__ == '__main__':
    raise SystemExit(_old.main())
